#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: first deploy of ace's hosted relay and account backend (docs/relay/accounts.md).
# Public values are kept in apps/relay-cloudflare/.deploy.env (git-ignored). Secrets go
# straight to Cloudflare and are never written to disk.
# ──────────────────────────────────────────────────────────────────────────
TOTAL_STAGES=9

cd "$(dirname "$0")/.."
ENV_FILE="$PWD/.deploy.env"
WRANGLER=(bunx wrangler)
PROD=(--env production)

# fill PLACEHOLDER VALUE: put a deploy value into wrangler.jsonc's production section.
fill() {
  if grep -q "$1" wrangler.jsonc; then
    local tmp; tmp=$(mktemp)
    sed "s|$1|$2|g" wrangler.jsonc > "$tmp" && mv "$tmp" wrangler.jsonc
    printf '  %s✓ set%s %s in wrangler.jsonc\n' "$GREEN" "$RESET" "$1"
  elif ! grep -q -- "$2" wrangler.jsonc; then
    warn "wrangler.jsonc already has another value where $1 was; edit it by hand to $2"
    SKIPPED+=("wrangler.jsonc: set $1 to $2")
  fi
}

# has_secret NAME: whether the deployed Worker already has this secret.
has_secret() { "${WRANGLER[@]}" secret list "${PROD[@]}" 2>/dev/null | grep -q "\"$1\""; }

banner "Deploy ace's hosted relay to Cloudflare"

stage "Domain and allowed origins"
say "The relay and the account API share one domain, e.g. relay.acehq.dev."
say "Its DNS zone must already be on the Cloudflare account you'll sign in with."
ask RELAY_DOMAIN "Relay domain (no https://):"
RELAY_DOMAIN="${RELAY_DOMAIN#https://}"; RELAY_DOMAIN="${RELAY_DOMAIN%/}"
say ""
say "Browser origins allowed to call the account API: the web app's exact origins,"
say "comma-separated, plus app://ace for the desktop app. Never a wildcard."
ask ALLOWED_ORIGINS "Allowed origins (e.g. https://app.acehq.dev,app://ace):"
write_env RELAY_DOMAIN "$RELAY_DOMAIN"
write_env ALLOWED_ORIGINS "$ALLOWED_ORIGINS"

stage "Sign in to Cloudflare"
say "Wrangler opens a browser tab; approve access for your Cloudflare account."
pause "Press Enter to start wrangler login"
"${WRANGLER[@]}" login
"${WRANGLER[@]}" whoami
note "If you belong to several Cloudflare accounts, set CLOUDFLARE_ACCOUNT_ID and re-run."
pause

stage "Create the accounts database"
ask D1_DATABASE_ID "Existing D1 database id for ace-accounts (Enter to create one):"
if [[ -z "$D1_DATABASE_ID" ]]; then
  if confirm "Create the D1 database ace-accounts now?"; then
    out=$("${WRANGLER[@]}" d1 create ace-accounts 2>&1) || { printf '%s\n' "$out"; exit 1; }
    printf '%s\n' "$out"
    D1_DATABASE_ID=$(printf '%s' "$out" | grep -oE '[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}' | head -n1)
    [[ -n "$D1_DATABASE_ID" ]] || ask D1_DATABASE_ID "Couldn't read the id; paste the database_id shown above:"
  else
    ask D1_DATABASE_ID "Paste the database id from 'bunx wrangler d1 list':"
  fi
fi
write_env D1_DATABASE_ID "$D1_DATABASE_ID"
fill PRODUCTION_DATABASE_ID "$D1_DATABASE_ID"

stage "Apply the database migrations"
say "This creates the sessions, sign-ins and machines tables (migrations/)."
if confirm "Apply migrations to the remote ace-accounts database?"; then
  "${WRANGLER[@]}" d1 migrations apply ACCOUNTS --remote "${PROD[@]}"
else
  SKIPPED+=("bunx wrangler d1 migrations apply ACCOUNTS --remote --env production")
fi
pause

stage "First deploy"
fill RELAY_DOMAIN "$RELAY_DOMAIN"
fill ALLOWED_ORIGINS "$ALLOWED_ORIGINS"
say "Deploying the Worker with its custom domain https://$RELAY_DOMAIN."
note "Until the secrets are set (next stages) it answers 503 for accounts and refuses relays."
if confirm "Deploy ace-relay to Cloudflare now?"; then
  "${WRANGLER[@]}" deploy "${PROD[@]}"
else
  SKIPPED+=("bunx wrangler deploy --env production")
fi
pause

stage "WorkOS: application and keys"
say "Use the WorkOS environment you want live users in (Production for real use)."
open_url "https://dashboard.workos.com/"
step "Applications → your AuthKit application → Redirects tab."
step "Add the redirect URI exactly: https://$RELAY_DOMAIN/v1/account/callback"
step "Open API Keys in the sidebar. Copy the Client ID (starts client_)."
ask WORKOS_CLIENT_ID "Paste the WorkOS Client ID:"
step "On the same page, copy the API key (Secret key)."
ask_secret WORKOS_API_KEY "Paste the WorkOS API key:"
write_env WORKOS_CLIENT_ID "$WORKOS_CLIENT_ID"

stage "Set the Worker's secrets"
printf '%s' "$WORKOS_CLIENT_ID" | "${WRANGLER[@]}" secret put WORKOS_CLIENT_ID "${PROD[@]}"
if [[ -n "$WORKOS_API_KEY" ]]; then
  printf '%s' "$WORKOS_API_KEY" | "${WRANGLER[@]}" secret put WORKOS_API_KEY "${PROD[@]}"
else
  SKIPPED+=("bunx wrangler secret put WORKOS_API_KEY --env production")
fi
# Generated keys are kept on re-runs: a new encryption key signs everyone out.
if has_secret ACE_ACCOUNT_ENCRYPTION_KEY && ! confirm "Replace ACE_ACCOUNT_ENCRYPTION_KEY? This signs everyone out."; then
  note "kept the existing ACE_ACCOUNT_ENCRYPTION_KEY"
else
  openssl rand -hex 32 | tr -d '\n' | "${WRANGLER[@]}" secret put ACE_ACCOUNT_ENCRYPTION_KEY "${PROD[@]}"
fi
# A rotation keeps the old key's public half published until its grants expire.
if has_secret ACE_GRANT_KEY && ! confirm "Rotate ACE_GRANT_KEY?"; then
  note "kept the existing ACE_GRANT_KEY"
else
  if has_secret ACE_GRANT_KEY; then
    previous=$(node -e '
      fetch(process.argv[1]).then((r) => r.json()).then((set) => {
        const key = set.keys[0];
        if (!/^[A-Za-z0-9_-]{1,64}$/.test(key.id) || !/^[A-Za-z0-9_-]{43}$/.test(key.publicKey)) process.exit(1);
        process.stdout.write(`${key.id}:${key.publicKey}`);
      }).catch(() => process.exit(1));' "https://$RELAY_DOMAIN/v1/keys") || previous=""
    if [[ -n "$previous" ]]; then
      printf '%s' "$previous" | "${WRANGLER[@]}" secret put ACE_GRANT_PREVIOUS_KEY "${PROD[@]}"
      note "grants signed by ${previous%%:*} stay valid until you delete ACE_GRANT_PREVIOUS_KEY"
      SKIPPED+=("in ten minutes: bunx wrangler secret delete ACE_GRANT_PREVIOUS_KEY --env production")
    else
      warn "couldn't read https://$RELAY_DOMAIN/v1/keys; grants in flight fail for up to five minutes"
    fi
  fi
  printf 'k%s:%s' "$(date +%Y%m%d%H%M)" "$(openssl rand -base64 32 | tr '+/' '-_' | tr -d '=\n')" \
    | "${WRANGLER[@]}" secret put ACE_GRANT_KEY "${PROD[@]}"
fi
pause

stage "Smoke check"
say "Checks the live Worker without an account and without leaving anything behind."
note "A new custom domain can take a few minutes for its certificate; re-run if it fails."
until node scripts/smoke.ts "https://$RELAY_DOMAIN"; do
  confirm "Try the smoke check again?" || { SKIPPED+=("bun run smoke https://$RELAY_DOMAIN"); break; }
done
pause

stage "Client settings"
say "Build and run clients against this backend with:"
step "Web and desktop builds: VITE_ACE_ACCOUNT_URL=https://$RELAY_DOMAIN"
step "Daemons: ACE_ACCOUNT_URL=https://$RELAY_DOMAIN ACE_HOSTED_RELAY_URL=wss://$RELAY_DOMAIN"
step "iOS: Xcode build setting ACE_ACCOUNT_URL=https://$RELAY_DOMAIN"
write_env ACE_ACCOUNT_URL "https://$RELAY_DOMAIN"
write_env ACE_HOSTED_RELAY_URL "wss://$RELAY_DOMAIN"
note "Commit the updated wrangler.jsonc so later deploys keep the domain and database."
pause "Press Enter to finish"

finish
